perf.naive:
def fewest_jumps(jumps: list[int]) -> int:
    n = len(jumps)
    best = [-1] * n                      # fewest jumps to each tile, -1 = not reached
    best[0] = 0
    for i in range(n):
        if best[i] < 0:
            continue
        for j in range(i + 1, min(n, i + jumps[i] + 1)):
            if best[j] < 0 or best[i] + 1 < best[j]:
                best[j] = best[i] + 1
    return best[-1]
